parameters.jsonBody:
={
  "contents": [
    {
      "parts": [
        {
          "text": "You are the review-analysis assistant for ReviewPulse AI. Analyze the customer review provided below. Return only valid raw JSON without markdown formatting: { \"sentiment\": \"positive\" | \"neutral\" | \"negative\", \"confidence\": 0.0 to 1.0, \"summary\": \"one concise sentence describing the main feedback\", \"suggested_reply\": \"polite, empathetic, professional reply addressing their feedback\", \"requires_human_review\": true | false } Customer review data: Reviewer: " + $('Webhook Trigger').item.json.body.reviewer_name + ", Product: " + ($('Webhook Trigger').item.json.body.product_name || 'General') + ", Rating: " + $('Webhook Trigger').item.json.body.rating + "/5, Review text: \"" + $('Webhook Trigger').item.json.body.review_text + "\""
        }
      ]
    }
  ],
  "generationConfig": {
    "responseMimeType": "application/json",
    "temperature": 0.2
  }
}

parameters.jsCode:
const geminiRaw = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
let parsed = {};
try {
  const clean = geminiRaw.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    sentiment: 'neutral',
    confidence: 0.85,
    summary: 'Customer feedback received.',
    suggested_reply: 'Thank you for your review. We appreciate your feedback!',
    requires_human_review: false
  };
}

const reviewId = $('Webhook Trigger').item.json.body.review_id || 1;

return {
  json: {
    review_id: reviewId,
    sentiment: parsed.sentiment || 'neutral',
    confidence: parsed.confidence || 0.95,
    summary: parsed.summary || 'Customer review feedback received.',
    suggested_reply: parsed.suggested_reply || 'Thank you for your feedback.',
    requires_human_review: parsed.requires_human_review ?? (parsed.sentiment === 'negative')
  }
};
